from typing import Optional, Tuple


@dataclass(frozen=True)
class SpeciesRuleset:
    """One set of environmental conditions under which a species can appear -
    a species may have several (any one matching is sufficient)."""

    atmosphere: Optional[Tuple[str, ...]] = None
    body_type: Optional[Tuple[str, ...]] = None
    min_gravity: Optional[float] = None
    max_gravity: Optional[float] = None
    min_temperature: Optional[float] = None
    max_temperature: Optional[float] = None
    min_pressure: Optional[float] = None
    max_pressure: Optional[float] = None
    volcanism: Optional[Tuple[str, ...]] = None  # specific required volcanism types, if any
    requires_volcanism: Optional[bool] = None  # True='Any' volcanism required, False=none allowed, None=unspecified
    star: Optional[Tuple[str, ...]] = None  # spectral class of the scanned body's illuminating star
    parent_star: Optional[Tuple[str, ...]] = None  # a different star in a multi-star system, if relevant
    bodies: Optional[Tuple[str, ...]] = None
    """At least one body of one of these PlanetClass values must exist
    somewhere in the system (not necessarily the body being scanned) -
    matched against organic_scan.BodyConditions.system_body_types, every
    PlanetClass scanned so far this system."""
    nebula: Optional[str] = None  # unused in v1 - proximity to a named nebula
    system: Optional[str] = None  # single-system special case, e.g. Radicoida Unicus
    max_orbital_period: Optional[float] = None  # days
    distance: Optional[float] = None  # body's own distance requirement, ls (rare - source-specific)
    regions: Optional[Tuple[str, ...]] = None
    """Named galactic-region code(s) the system must be in (organic_region_data.py's
    REGION_GROUPS keys) - a leading '!' negates one entry (must NOT be in that
    region). Matched against organic_scan.BodyConditions.galactic_region_id, itself
    computed offline from the system's own journal-reported StarPos - see
    organic_region_data.py's module docstring. A system whose region can't be
    determined (outside the mapped area) is never eliminated by this condition,
    same "unknown doesn't eliminate" principle as every other unset/unknown field
    here."""
    guardian: Optional[bool] = None
    """True: the system must be within one of organic_region_data.GUARDIAN_ZONES'
    named nebulae - checked by straight-line distance from the system's own
    StarPos, same data/method as `regions` above."""
    atmosphere_component: Optional[Tuple[Tuple[str, float], ...]] = None
    """(trace gas name, minimum percent) pairs - all must be met. From the body's
    own Scan event `AtmosphereComposition` array, not `AtmosphereType` (which only
    names the dominant gas) - see organic_scan.BodyConditions.atmosphere_components."""
    tuber: Optional[Tuple[str, ...]] = None
    """Bark Mound (Sinuous Tubers) only - named zone(s) (organic_region_data.py's
    TUBER_ZONES keys) the system must fall within the (min_ly, max_ly) distance
    band of at least one of, or the single entry 'Any' to accept any zone. Same
    straight-line-distance-from-StarPos method as `guardian` above, against a
    different, larger set of named reference points - not the same condition,
    despite the shape similarity."""


